using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;

namespace Prometheus {
 public sealed class NestedInlineView0106:Control {
  readonly Timeline timeline;Project project;Clip outer;NestedContent0910 content;List<string> lanes=new List<string>();
  string expandedChildId;Clip expandedChild;NestedContent0910 expandedContent;List<string> expandedLanes=new List<string>();
  string dragging;bool draggingInner;int dragMode;Point origin;double oldStart,oldDuration,previewStart,previewDuration;string previewTrack;
  const int Row=27,Header=25;
  public Action<string,string,double,double,string> ChildChanged;public Action<string,string> EditChildRequested,RemoveChildRequested;public Action CloseRequested;
  public string OuterId{get{return outer==null?null:outer.id;}}
  public NestedInlineView0106(Timeline owner){timeline=owner;DoubleBuffered=true;BackColor=Color.FromArgb(32,35,40);ForeColor=Color.Gainsboro;Visible=false;Height=0;SetStyle(ControlStyles.ResizeRedraw,true);}
  public void Set(Project p,string clipId){bool same=outer!=null&&outer.id==clipId;if(!same)expandedChildId=null;project=p;outer=p==null?null:p.Active.clips.Find(c=>c.id==clipId);content=NestedMedia0910.IsNested(p,outer)?NestedMedia0910.Read(outer):null;lanes=new List<string>();expandedLanes=new List<string>();expandedChild=null;expandedContent=null;if(content!=null){string component=NestedMedia0910.Component(outer);if(component!="audio")lanes.AddRange(content.video_orders.OrderByDescending(x=>x.Value).Select(x=>x.Key));if(component!="video")lanes.AddRange(content.audio_orders.OrderBy(x=>x.Value).Select(x=>x.Key));expandedChild=content.clips.Find(c=>c.id==expandedChildId&&NestedMedia0910.IsNested(p,c));if(expandedChild!=null){expandedContent=NestedMedia0910.Read(expandedChild);bool audio=content.audio_orders.ContainsKey(expandedChild.track_id);expandedLanes.AddRange((audio?expandedContent.audio_orders.OrderBy(x=>x.Value):expandedContent.video_orders.OrderByDescending(x=>x.Value)).Select(x=>x.Key));}}Height=content==null?0:Header+(lanes.Count+expandedLanes.Count)*Row+2;Visible=content!=null;timeline.SetInlineNested(this,clipId,Height);Invalidate();}
  int LabelWidth{get{return timeline.HeaderWidth;}}
  double PixelsPerSecond{get{return timeline.Zoom;}}
  int LaneY(int index){return Header+index*Row;}
  Rectangle ChildRect(Clip child){int lane=lanes.IndexOf(child.track_id);double speed=Math.Max(.001,outer.speed.Seconds),start=outer.timeline_start.Seconds+(child.timeline_start.Seconds-outer.source_in.Seconds)/speed;return new Rectangle((int)Math.Round(timeline.X(start)),LaneY(lane)+3,Math.Max(6,(int)Math.Round(child.duration.Seconds/speed*PixelsPerSecond)),Row-6);}
  Rectangle InnerRect(Clip child){int lane=expandedLanes.IndexOf(child.track_id);double speed=Math.Max(.001,outer.speed.Seconds*expandedChild.speed.Seconds),start=outer.timeline_start.Seconds+(expandedChild.timeline_start.Seconds+(child.timeline_start.Seconds-expandedChild.source_in.Seconds)/expandedChild.speed.Seconds-outer.source_in.Seconds)/outer.speed.Seconds;return new Rectangle((int)Math.Round(timeline.X(start)),LaneY(lanes.Count+lane)+3,Math.Max(6,(int)Math.Round(child.duration.Seconds/speed*PixelsPerSecond)),Row-6);}
  Clip InnerHit(Point point){return expandedContent==null?null:expandedContent.clips.Where(c=>expandedLanes.Contains(c.track_id)).LastOrDefault(c=>InnerRect(c).Contains(point));}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.Clear(BackColor);if(content==null)return;
   using(var header=new SolidBrush(Color.FromArgb(45,48,54)))g.FillRectangle(header,0,0,Width,Header);
   string kind=NestedMedia0910.Component(outer)=="audio"?"audio":"vídeo";
   TextRenderer.DrawText(g,"Dentro de "+outer.name+" · "+kind,Font,new Rectangle(8,3,Math.Max(30,Width-108),20),Color.White,TextFormatFlags.EndEllipsis);
   TextRenderer.DrawText(g,"Listo  ×",Font,new Rectangle(Width-82,3,75,20),Color.FromArgb(255,178,91),TextFormatFlags.Right);
   for(int i=0;i<lanes.Count;i++){bool audio=content.audio_orders.ContainsKey(lanes[i]);int y=LaneY(i);using(var brush=new SolidBrush(i%2==0?Color.FromArgb(34,38,44):Color.FromArgb(39,43,49)))g.FillRectangle(brush,0,y,Width,Row);TextRenderer.DrawText(g,(audio?"A":"V")+" · pista interna",Font,new Rectangle(8,y+5,LabelWidth-14,18),Color.FromArgb(178,187,197),TextFormatFlags.EndEllipsis);using(var line=new Pen(Color.FromArgb(55,59,65)))g.DrawLine(line,0,y+Row-1,Width,y+Row-1);}
   for(int i=0;i<expandedLanes.Count;i++){int y=LaneY(lanes.Count+i);using(var brush=new SolidBrush(Color.FromArgb(49,37,53)))g.FillRectangle(brush,0,y,Width,Row);TextRenderer.DrawText(g,(expandedContent.audio_orders.ContainsKey(expandedLanes[i])?"A":"V")+" · nivel 2",Font,new Rectangle(19,y+5,LabelWidth-25,18),Color.FromArgb(237,185,225),TextFormatFlags.EndEllipsis);using(var line=new Pen(Color.FromArgb(88,57,92)))g.DrawLine(line,0,y+Row-1,Width,y+Row-1);}
   var state=g.Save();g.SetClip(new Rectangle(LabelWidth,Header,Math.Max(1,Width-LabelWidth),Math.Max(1,Height-Header)));
   foreach(var child in content.clips.Where(c=>lanes.Contains(c.track_id))){var rect=ChildRect(child);if(child.id==dragging&&!draggingInner){rect.X=(int)Math.Round(timeline.X(outer.timeline_start.Seconds+(previewStart-outer.source_in.Seconds)/Math.Max(.001,outer.speed.Seconds)));rect.Width=Math.Max(6,(int)Math.Round(previewDuration/Math.Max(.001,outer.speed.Seconds)*PixelsPerSecond));}bool audio=content.audio_orders.ContainsKey(child.track_id),nested=NestedMedia0910.IsNested(project,child);using(var fill=new SolidBrush(audio?Color.FromArgb(83,151,188):nested?Color.FromArgb(176,116,176):Color.FromArgb(222,145,75)))g.FillRectangle(fill,rect);using(var edge=new Pen(nested?Color.FromArgb(255,204,245):Color.FromArgb(245,230,221),nested?2:1))g.DrawRectangle(edge,rect);TextRenderer.DrawText(g,(nested?(child.id==expandedChildId?"▾ ":"▸ "):"")+child.name,Font,new Rectangle(rect.X+5,rect.Y+2,Math.Max(1,rect.Width-10),rect.Height-4),Color.FromArgb(22,24,28),TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter);}
   if(expandedContent!=null)foreach(var child in expandedContent.clips.Where(c=>expandedLanes.Contains(c.track_id))){var rect=InnerRect(child);if(child.id==dragging&&draggingInner){double speed=Math.Max(.001,outer.speed.Seconds*expandedChild.speed.Seconds);rect.X=(int)Math.Round(timeline.X(outer.timeline_start.Seconds+(expandedChild.timeline_start.Seconds+(previewStart-expandedChild.source_in.Seconds)/expandedChild.speed.Seconds-outer.source_in.Seconds)/outer.speed.Seconds));rect.Width=Math.Max(6,(int)Math.Round(previewDuration/speed*PixelsPerSecond));}using(var fill=new SolidBrush(expandedContent.audio_orders.ContainsKey(child.track_id)?Color.FromArgb(96,156,190):Color.FromArgb(200,150,195)))g.FillRectangle(fill,rect);using(var edge=new Pen(Color.FromArgb(255,218,241)))g.DrawRectangle(edge,rect);TextRenderer.DrawText(g,child.name,Font,new Rectangle(rect.X+5,rect.Y+2,Math.Max(1,rect.Width-10),rect.Height-4),Color.FromArgb(22,24,28),TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter);}
   g.Restore(state);
  }
  int EdgeAt(Rectangle bounds,int x){int grip=Math.Min(8,Math.Max(2,bounds.Width/3));return x<bounds.Left+grip?1:x>=bounds.Right-grip?2:0;}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(content==null)return;if(e.Y<Header){if(e.Button==MouseButtons.Left&&e.X>Width-90&&CloseRequested!=null)CloseRequested();return;}
   var inner=InnerHit(e.Location);bool isInner=inner!=null;var hit=inner??content.clips.Where(c=>lanes.Contains(c.track_id)).LastOrDefault(c=>ChildRect(c).Contains(e.Location));if(hit==null)return;
   if(!isInner&&e.Button==MouseButtons.Left&&e.Clicks>1&&NestedMedia0910.IsNested(project,hit)){expandedChildId=expandedChildId==hit.id?null:hit.id;Set(project,outer.id);return;}
   if(e.Button==MouseButtons.Right){string parent=outer.id,child=hit.id;var menu=new ContextMenuStrip();if(!isInner&&NestedMedia0910.IsNested(project,hit))menu.Items.Add(expandedChildId==hit.id?"Replegar contenido":"Desplegar contenido",null,(s,a)=>{expandedChildId=expandedChildId==child?null:child;Set(project,parent);});menu.Items.Add("Propiedades del componente…",null,(s,a)=>{if(EditChildRequested!=null)EditChildRequested(parent,child);});menu.Items.Add("Quitar del medio anidado",null,(s,a)=>{if(RemoveChildRequested!=null)RemoveChildRequested(parent,child);});menu.Closed+=(s,a)=>BeginInvoke((Action)(()=>menu.Dispose()));menu.Show(this,e.Location);return;}
   if(e.Button!=MouseButtons.Left)return;var bounds=isInner?InnerRect(hit):ChildRect(hit);dragging=hit.id;draggingInner=isInner;dragMode=EdgeAt(bounds,e.X);origin=e.Location;oldStart=previewStart=hit.timeline_start.Seconds;oldDuration=previewDuration=hit.duration.Seconds;previewTrack=hit.track_id;Capture=true;Cursor=dragMode==0?Cursors.SizeAll:Cursors.SizeWE;Invalidate();
  }
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(content==null)return;if(dragging==null){var inner=InnerHit(e.Location);var hit=inner??content.clips.Where(c=>lanes.Contains(c.track_id)).LastOrDefault(c=>ChildRect(c).Contains(e.Location));Cursor=hit==null?Cursors.Default:EdgeAt(inner==null?ChildRect(hit):InnerRect(hit),e.X)==0?Cursors.SizeAll:Cursors.SizeWE;return;}
   double delta=(e.X-origin.X)/PixelsPerSecond*outer.speed.Seconds*(draggingInner?expandedChild.speed.Seconds:1),step=1.0/60;delta=Math.Round(delta/step)*step;var active=draggingInner?expandedContent:content;var child=active.clips.Find(c=>c.id==dragging);var asset=project.assets.Find(a=>a.id==child.asset_id);var stream=asset==null?null:asset.streams.Find(s=>s.id==child.stream_id);double maximum=stream==null||stream.duration==null?48*3600:(stream.duration.Seconds-child.source_in.Seconds)/child.speed.Seconds;
   if(dragMode==2)previewDuration=Math.Max(step,Math.Min(maximum,oldDuration+delta));else if(dragMode==1){double earliest=Math.Max(0,oldStart-child.source_in.Seconds/child.speed.Seconds);previewStart=Math.Max(earliest,Math.Min(oldStart+oldDuration-step,oldStart+delta));previewDuration=oldDuration+oldStart-previewStart;}else{previewStart=Math.Max(0,oldStart+delta);int row=(e.Y-Header)/Row;if(draggingInner){int innerRow=row-lanes.Count;if(innerRow>=0&&innerRow<expandedLanes.Count&&active.audio_orders.ContainsKey(child.track_id)==active.audio_orders.ContainsKey(expandedLanes[innerRow]))previewTrack=expandedLanes[innerRow];}else if(row>=0&&row<lanes.Count&&content.audio_orders.ContainsKey(child.track_id)==content.audio_orders.ContainsKey(lanes[row]))previewTrack=lanes[row];}Invalidate();
  }
  protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(dragging==null)return;string id=dragging;var active=draggingInner?expandedContent:content;dragging=null;draggingInner=false;Capture=false;double start=previewStart,duration=previewDuration;string track=previewTrack;Invalidate();if(Math.Abs(start-oldStart)>0.00001||Math.Abs(duration-oldDuration)>0.00001||track!=active.clips.Find(c=>c.id==id).track_id)if(ChildChanged!=null)ChildChanged(outer.id,id,start,duration,track);}
 }
